def is_palindrome(s):
    """
    Check if a string is a palindrome
    """
    if s == s[::-1]:
        return True
    else:
        return False

print(is_palindrome('radar'))

# Write a Python function to check whether a string is pangram or not. Include docstrings and an example.

def is_pangram(s):
    """
    Check if a string is pangram
    """
    for i in 'abcdefghijklmnopqrstuvwxyz':
        if i not in s.lower():
            return False
    return True

print(is_pangram('The quick brown fox jumps over the lazy dog'))

